import React, { useState, useEffect } from 'react';

interface ProductImage {
  id: number;
  src: string;
  alt: string;
  title: string;
  description: string;
}

const ProductCarousel: React.FC = () => {
  // Dữ liệu hình ảnh sản phẩm (bạn có thể thay thế bằng hình ảnh thật)
  const productImages: ProductImage[] = [
    {
      id: 1,
      src: "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=500&h=400&fit=crop&crop=center",
      alt: "Túi shopping nhỏ Scoby",
      title: "Túi Shopping Nhỏ",
      description: "Kích thước 25x30cm, phù hợp cho việc mua sắm hàng ngày"
    },
    {
      id: 2,
      src: "https://images.unsplash.com/photo-1594223274512-ad4803739b7c?w=500&h=400&fit=crop&crop=center",
      alt: "Túi shopping lớn Scoby",
      title: "Túi Shopping Lớn",
      description: "Kích thước 35x40cm, lý tưởng cho việc mua sắm lớn"
    },
    {
      id: 3,
      src: "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=500&h=400&fit=crop&crop=center",
      alt: "Túi đựng đồ cá nhân Scoby",
      title: "Túi Cá Nhân",
      description: "Kích thước 20x25cm, hoàn hảo cho đồ dùng cá nhân"
    },
    {
      id: 4,
      src: "https://images.unsplash.com/photo-1601925260369-5a5a4b4b4b4b?w=500&h=400&fit=crop&crop=center",
      alt: "Túi đựng thực phẩm Scoby",
      title: "Túi Thực Phẩm",
      description: "Kích thước 30x35cm, an toàn cho thực phẩm"
    },
    {
      id: 5,
      src: "https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=500&h=400&fit=crop&crop=center",
      alt: "Quy trình sản xuất Scoby",
      title: "Quy Trình Sản Xuất",
      description: "Từ con scoby đến sản phẩm túi hoàn chỉnh"
    }
  ];

  const [currentIndex, setCurrentIndex] = useState(0);

  // Tự động chuyển ảnh mỗi 4 giây
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentIndex((prevIndex) => 
        prevIndex === productImages.length - 1 ? 0 : prevIndex + 1
      );
    }, 4000);

    return () => clearInterval(interval);
  }, [productImages.length]);

  const goToSlide = (index: number) => {
    setCurrentIndex(index);
  };

  const goToPrevious = () => {
    setCurrentIndex(currentIndex === 0 ? productImages.length - 1 : currentIndex - 1);
  };

  const goToNext = () => {
    setCurrentIndex(currentIndex === productImages.length - 1 ? 0 : currentIndex + 1);
  };

  return (
    <div className="relative w-full max-w-4xl mx-auto">
      {/* Carousel Container */}
      <div className="relative overflow-hidden rounded-lg shadow-2xl">
        {/* Images */}
        <div 
          className="flex transition-transform duration-500 ease-in-out"
          style={{ transform: `translateX(-${currentIndex * 100}%)` }}
        >
          {productImages.map((image) => (
            <div key={image.id} className="w-full flex-shrink-0 relative">
              <img
                src={image.src}
                alt={image.alt}
                className="w-full h-96 object-cover"
              />
              {/* Overlay with product info */}
              <div className="absolute inset-0 bg-black bg-opacity-40 flex items-end">
                <div className="p-6 text-white">
                  <h3 className="text-2xl font-bold mb-2">{image.title}</h3>
                  <p className="text-lg">{image.description}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Navigation Arrows */}
        <button
          onClick={goToPrevious}
          className="absolute left-4 top-1/2 transform -translate-y-1/2 bg-white bg-opacity-80 hover:bg-opacity-100 text-gray-800 p-2 rounded-full shadow-lg transition-all duration-200"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
        </button>

        <button
          onClick={goToNext}
          className="absolute right-4 top-1/2 transform -translate-y-1/2 bg-white bg-opacity-80 hover:bg-opacity-100 text-gray-800 p-2 rounded-full shadow-lg transition-all duration-200"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </button>
      </div>

      {/* Dots Indicator */}
      <div className="flex justify-center mt-4 space-x-2">
        {productImages.map((_, index) => (
          <button
            key={index}
            onClick={() => goToSlide(index)}
            className={`w-3 h-3 rounded-full transition-all duration-200 ${
              index === currentIndex 
                ? 'bg-green-600 w-8' 
                : 'bg-gray-300 hover:bg-gray-400'
            }`}
          />
        ))}
      </div>

      {/* Product Counter */}
      <div className="text-center mt-2 text-gray-600">
        <span className="text-sm">
          {currentIndex + 1} / {productImages.length}
        </span>
      </div>
    </div>
  );
};

export default ProductCarousel;
